import React, { createContext, useState, useContext, useEffect } from "react";
import { auth, googleProvider } from "../../../firebase";
import { signInWithPopup, signOut, onAuthStateChanged } from "firebase/auth";
import {
  API_BASE_URL,
  saveAuthToken,
  getSavedAuthToken,
  clearSavedAuth,
  saveUserProfile,
  getSavedUserProfile,
  apiFetch,
} from "../../../api/apiClient";

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => getSavedUserProfile());
  const [loading, setLoading] = useState(true);

  const syncFirebaseUserWithBackend = async (firebaseUser) => {
    const token = await firebaseUser.getIdToken(); // JWT від Firebase
    saveAuthToken(token);

    const fallbackUser = {
      uid: firebaseUser.uid,
      name: firebaseUser.displayName || firebaseUser.email?.split("@")[0] || "Користувач",
      email: firebaseUser.email,
      photo: firebaseUser.photoURL,
    };

    try {
      // Синхронізуємо юзера з бекендом
      const response = await fetch(`${API_BASE_URL}/api/auth/sync`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          name: firebaseUser.displayName,
          email: firebaseUser.email,
          photo: firebaseUser.photoURL,
        }),
      });

      const authHeader = response.headers.get("Authorization");
      if (authHeader) {
        saveAuthToken(authHeader);
      }

      if (response.ok) {
        const syncedData = await response.json().catch(() => null);
        const finalUser = {
          uid: syncedData?.uid || fallbackUser.uid,
          name: syncedData?.name || fallbackUser.name,
          email: syncedData?.email || fallbackUser.email,
          photo: syncedData?.photo || fallbackUser.photo,
        };
        saveUserProfile(finalUser);
        setUser(finalUser);
        return finalUser;
      }
    } catch (error) {
      console.warn("Не вдалося синхронізувати користувача з бекендом:", error);
    }

    saveUserProfile(fallbackUser);
    setUser(fallbackUser);
    return fallbackUser;
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        await syncFirebaseUserWithBackend(firebaseUser);
        setLoading(false);
        return;
      }

      // Якщо немає сесії Firebase, перевіряємо збережений JWT від бекенду
      const savedToken = getSavedAuthToken();
      if (savedToken) {
        try {
          const profile = await apiFetch("/api/users/me", {
            headers: { Authorization: `Bearer ${savedToken}` },
          });
          if (profile) {
            saveUserProfile(profile);
            setUser(profile);
          }
        } catch (error) {
          if (error.status === 401 || error.status === 403) {
            clearSavedAuth();
            setUser(null);
          } else {
            // Якщо бекенд тимчасово недоступний, залишаємо збережений профіль
            const cachedUser = getSavedUserProfile();
            setUser(cachedUser);
          }
        }
      } else {
        setUser(null);
      }

      setLoading(false);
    });

    return unsubscribe;
  }, []);

  // 1. Логін через GoogleAuthProvider на фронті + синхронізація з бекендом
  const loginWithGoogle = async () => {
    const result = await signInWithPopup(auth, googleProvider);
    return await syncFirebaseUserWithBackend(result.user);
  };

  // Допоміжна функція для обробки відповіді /api/auth/login та /api/auth/register
  const handleBackendAuthResponse = async (response, fallbackInfo = {}) => {
    let data = null;
    try {
      data = await response.json();
    } catch {
      data = null;
    }

    if (!response.ok) {
      throw new Error(
        data?.message || data?.error || `Помилка авторизації (${response.status})`,
      );
    }

    const authHeader = response.headers.get("Authorization"); // "Bearer <jwt>"
    const tokenFromBody = data?.token || data?.accessToken || data?.jwt;

    if (authHeader) {
      saveAuthToken(authHeader);
    } else if (tokenFromBody) {
      saveAuthToken(tokenFromBody);
    }

    // Отримуємо дані профілю з відповіді або через GET /api/users/me
    let userProfile = null;
    if (data && (data.email || data.uid || data.name)) {
      userProfile = {
        uid: data.uid || data.id || fallbackInfo.email,
        name:
          data.name ||
          fallbackInfo.name ||
          (data.email || fallbackInfo.email)?.split("@")[0] ||
          "Користувач",
        email: data.email || fallbackInfo.email,
        photo: data.photo || data.photoUrl || null,
      };
    } else {
      try {
        userProfile = await apiFetch("/api/users/me");
      } catch {
        userProfile = {
          uid: fallbackInfo.email,
          name:
            fallbackInfo.name ||
            fallbackInfo.email?.split("@")[0] ||
            "Користувач",
          email: fallbackInfo.email,
          photo: null,
        };
      }
    }

    saveUserProfile(userProfile);
    setUser(userProfile);
    return userProfile;
  };

  // 2. Логін через бекенд (POST /api/auth/login)
  const loginWithBackend = async (email, password) => {
    const response = await fetch(`${API_BASE_URL}/api/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });

    return await handleBackendAuthResponse(response, { email });
  };

  // 3. Реєстрація через бекенд (POST /api/auth/register)
  const registerWithBackend = async ({ name, email, password }) => {
    const response = await fetch(`${API_BASE_URL}/api/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, email, password }),
    });

    return await handleBackendAuthResponse(response, { name, email });
  };

  const logout = async () => {
    clearSavedAuth();
    setUser(null);
    try {
      await signOut(auth);
    } catch (error) {
      console.warn("Sign out error:", error);
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        loginWithGoogle,
        loginWithBackend,
        registerWithBackend,
        logout,
      }}
    >
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
