import { auth } from "../firebase";

export const API_BASE_URL =
  process.env.REACT_APP_API_URL || "http://localhost:8080";

const TOKEN_STORAGE_KEY = "train_app_auth_token";
const USER_STORAGE_KEY = "train_app_user";

export const saveAuthToken = (tokenOrHeader) => {
  if (!tokenOrHeader) return;
  const rawToken = tokenOrHeader.startsWith("Bearer ")
    ? tokenOrHeader.slice(7).trim()
    : tokenOrHeader.trim();
  localStorage.setItem(TOKEN_STORAGE_KEY, rawToken);
};

export const getSavedAuthToken = () => {
  return localStorage.getItem(TOKEN_STORAGE_KEY);
};

export const clearSavedAuth = () => {
  localStorage.removeItem(TOKEN_STORAGE_KEY);
  localStorage.removeItem(USER_STORAGE_KEY);
};

export const saveUserProfile = (userObj) => {
  if (!userObj) {
    localStorage.removeItem(USER_STORAGE_KEY);
    return;
  }
  localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(userObj));
};

export const getSavedUserProfile = () => {
  try {
    const raw = localStorage.getItem(USER_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};

export const getAuthorizationHeader = async () => {
  // 1. If there is a saved JWT token (from backend login/register or synced session), prefer it or refresh Firebase token
  if (auth.currentUser) {
    try {
      const firebaseToken = await auth.currentUser.getIdToken();
      saveAuthToken(firebaseToken);
      return `Bearer ${firebaseToken}`;
    } catch (err) {
      console.warn("Failed to get Firebase ID token:", err);
    }
  }

  const savedToken = getSavedAuthToken();
  if (savedToken) {
    return `Bearer ${savedToken}`;
  }

  return null;
};

export const apiFetch = async (path, options = {}) => {
  const url = path.startsWith("http") ? path : `${API_BASE_URL}${path}`;
  const headers = {
    "Content-Type": "application/json",
    ...(options.headers || {}),
  };

  if (!headers.Authorization) {
    const authHeader = await getAuthorizationHeader();
    if (authHeader) {
      headers.Authorization = authHeader;
    }
  }

  const response = await fetch(url, {
    ...options,
    headers,
  });

  if (response.status === 204) {
    return null;
  }

  let data = null;
  const contentType = response.headers.get("content-type") || "";
  if (contentType.includes("application/json")) {
    try {
      data = await response.json();
    } catch {
      data = null;
    }
  } else {
    try {
      const text = await response.text();
      data = text ? JSON.parse(text) : null;
    } catch {
      data = null;
    }
  }

  if (!response.ok) {
    const error = new Error(
      data?.message || data?.error || `HTTP Error ${response.status}`,
    );
    error.status = response.status;
    error.code = data?.code;
    error.data = data;
    throw error;
  }

  return data;
};
